    out.put("Belagan", new NpcScripts.Entry(
        "Belagan",
        "NPC RavensDust/Belagan.cpp",
        "BelaganNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.4209}\")\n\t\nCommand2(INTL(\"${npc.cpp.intl.3694}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.4210}\")\n\nCommand(INTL(\"${npc.cpp.intl.3903}\"))\nINTL(\"${npc.cpp.intl.4211}\")\n\nCommand2(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.3696}\"))\nINTL(\"${npc.cpp.intl.4212}\")\n\nCommand(INTL(\"${npc.cpp.intl.3880}\"))\nINTL( 4213, \"Adriana is the mistress here. She is often too busy \\\"training\\\" adventurers in the art of war, \"\n\"so I take care of the everyday tasks, such as \\\"cleaning\\\" and \\\"cooking\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.4214}\"))\nINTL( 4215, \"Just like I said, Adriana takes care of that. If you seek to improve your skills or learn \"\n\"new ones, go seek her out.\")\n\nCommand2(INTL(\"${npc.cpp.intl.3905}\"),INTL(\"${npc.cpp.intl.3906}\"))\n\"\"\nSWITCH(CheckFlag(__QUEST_ROYAL_KEY1))\n\tCASE(0) // Hasn't talked to Celydia yet...\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.4216}\")\n\tENDCASE\n\tCASE(1) // Has talked to Celydia...\n\t\tConversation\n\t\tINTL( 4217, \"I... can't really talk much about it, in case Mistress Adriana finds out. She gets \"\n\t\t\"very upset when someone mentions his name. Perhaps if you'll do me a favor, it'll be \"\n\t\t\"worth my while to talk to you. Would you do that?\")\n\t\tSetYesNo(FAVOR)\n\tENDCASE\n\tCASE(2) // Has received but not completed Book of Warfare Quest.\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.4218}\")\n\tENDCASE\n\tCASE(3) // Brought the Book back.\n\t\tConversation\n\t\tINTL( 4219, \"Ah, yes, about Aspicdart... Well, there was an affair between him and my mistress, \"\n\t\t\"a few years ago, and it ended pretty sourly. I know she considered going after him \"\n\t\t\"when she learned he had gone to the \\\"Cave\\\" \\\"of\\\" \\\"Illusions\\\", but her work here was enough \"\n\t\t\"to keep her from going... barely.\")\n\t\tGiveFlag(__QUEST_ROYAL_KEY1,4)\n\tENDCASE\n\tCASE(4) // Already knows about Aspicdart.\n\t\tConversation\n\t\tINTL( 4220, \"I've told you all I know about him. Now seek him in the Cave of Illusions, wherever \"\n\t\t\"that may be.\")\n\tENDCASE\n\tOTHERWISE // Has already gone way past this point in the quest.\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.4221}\")\n\tENDCASE\nENDSWITCH\n\nYES(FAVOR)\nConversation\nINTL( 4222, \"Very well... I would like to some day impress my mistress with my knowledge of tactics, \"\n\"so she notices me as more than just a cook, but I can't find any books to help me. If \"\n\"you could seek a copy of \\\"Kerthew's\\\" \\\"Book\\\" \\\"of\\\" \\\"Warfare\\\", I would be eternally grateful.\")\nIF (CheckFlag(__QUEST_ROYAL_KEY1) == 1)\n\tGiveFlag(__QUEST_ROYAL_KEY1,2)\nENDIF\n\nNO(FAVOR)\nConversation\nINTL(\"${npc.cpp.intl.4223}\")\n\nYesNoELSE(FAVOR)\nConversation\nINTL(\"${npc.cpp.intl.2422}\")\n\nCommand(INTL(\"${npc.cpp.intl.4224}\"))\nINTL(\"${npc.cpp.intl.4225}\")\n\nCommand2(INTL(\"${npc.cpp.intl.4002}\"),INTL(\"${npc.cpp.intl.4003}\"))\nINTL(\"${npc.cpp.intl.4226}\")\n\nCommand(INTL(\"${npc.cpp.intl.3908}\"))\nINTL(\"${npc.cpp.intl.4227}\")\nIF ((CheckItem(__OBJ_BOOK_OF_WARFARE) >= 1) && (CheckFlag(__QUEST_ROYAL_KEY1) == 2))\n\tConversation\n\tINTL(\"${npc.cpp.intl.4228}\")\n\tTakeItem(__OBJ_BOOK_OF_WARFARE)\n\tGiveFlag(__QUEST_ROYAL_KEY1,3)\nELSE\n\tConversation\n\tINTL( 4229, \" I would LOVE to get a copy of it, but there are so few available... A collector's \"\n\t\"item! I'm sure Adriana wouldn't mind a copy either.\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.4230}\"))\nINTL( 4231, \"I don't mind the work, since I do get to spend some time with Adriana, and I don't have to \"\n\"pay for my room.\")\n\nCommand(INTL(\"${npc.cpp.intl.3916}\"))\nINTL( 4232, \"Ahhh, now that I enjoy doing. I can practice my cooking skills and eventually maybe open my \"\n\"own tavern or something like it.\")\n\nCommand(INTL(\"${npc.cpp.intl.4233}\"))\nINTL(\"${npc.cpp.intl.4234}\")\n\nCommand(INTL(\"${npc.cpp.intl.3918}\"))\n\"\"\nIF (CheckFlag(__QUEST_VISITOR_SPOTTED) == 0)\n\tIF (CheckFlag(__QUEST_DAMIEN_SUBPLOT) == 2)\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.4235}\")\n\t\tGiveFlag(__QUEST_VISITOR_SPOTTED, 1)\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.4236}\")\n\tENDIF\nELSEIF (CheckFlag(__QUEST_VISITOR_SPOTTED) == 1)\n\tConversation\n\tINTL( 4237, \"Hmm, come to think of it, I have seen a rather strange person recently. I believe he was walking \"\n\t\"in the direction of Nafuhr's shop.\")\n\tGiveFlag(__QUEST_VISITOR_SPOTTED, 2)\nELSEIF (CheckFlag(__QUEST_VISITOR_SPOTTED) >= 2)\n\tConversation\n\tINTL(\"${npc.cpp.intl.4238}\")\nENDIF\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.973}\")\nBREAK\n\nDefault\nINTL(\"${npc.cpp.intl.4239}\")\n\nEndTalk",
        Map.of()));
    out.put("BeltiganWhitesword", new NpcScripts.Entry(
        "BeltiganWhitesword",
        "NPC Stoneheim/BeltiganWhitesword.cpp",
        "BeltiganWhiteswordNPC",
        "CONSTANT LIGHTBRINGER = 1; \nCONSTANT Pledge = 2;\nCONSTANT MergeItems = 3; \nCONSTANT TakeRings = 4;\n\n\nInitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.8578}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.8579}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.487}\"),INTL(\"${npc.cpp.intl.488}\"))\nINTL(\"${npc.cpp.intl.8580}\")\n\nCommand(INTL(\"${npc.cpp.intl.8581}\"))\nINTL(\"${npc.cpp.intl.8582}\")\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == -1) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8583}\")\nENDIF\n \nCommand(INTL(\"${npc.cpp.intl.8584}\")) \n\"\"\nIF(CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1)\n\tConversation\n\tINTL( 8585, \"Since the past few thousand years, there has been one who's evil power has grown steadily. Since a balance has to be kept, \"\n\t\"what is gained must be lost somewhere. So great his power has become that he poses a serious \\\"threat\\\" to everybody, even to \"\n\t\"Artherk himself.\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCmdAND(INTL(\"${npc.cpp.intl.8039}\"),INTL(\"${npc.cpp.intl.8040}\"))\n\"\"\nIF((USER_KARMA < 100) || (CheckFlag(__QUEST_FIXED_ALIGNMENT) == -1))\n\tConversation\n\tINTL(\"${npc.cpp.intl.8587}\")\nELSE\n\tIF (CheckItem(__OBJ_RING_OF_THE_LION)<2)\n\t\tConversation\n\t\tINTL( 8588, \"Those rings would help raise the courage and morale of my warriors. Should you have two to spare, \"\n\t\t\"I would reward you handsomely.\")\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8589}\")\n\t\tSetYesNo(TakeRings)\n\tENDIF\nENDIF\n\nYES(TakeRings)\n\tIF (CheckItem(__OBJ_RING_OF_THE_LION) < 2)\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8590}\")\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.8591}\")\n\t\tFOR(0,2)\n\t\t\tTakeItem(__OBJ_RING_OF_THE_LION)\n\t\tENDFOR\n\t\tIF (rnd.roll(dice(1,2)) == 1)\n\t\t\tConversation\n\t\t\tINTL(\"${npc.cpp.intl.8592}\")\n\t\t\tGiveItem(__OBJ_CRYSTAL_SWORD_OF_MIGHT)\n\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8593}\")) \n\t\tELSE\n\t\t\tConversation\n\t\t\tINTL(\"${npc.cpp.intl.8594}\")\n\t\t\tGiveItem(__OBJ_EYE_OF_THE_TIGER)\n\t\t\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.8595}\")) \n\t\tENDIF\n\t\t;int nExpReward = USER_LEVEL*4000;\n\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7982}\"), nExpReward) ) \n\t\tGiveXP(nExpReward)\n\tENDIF\n\nNO(TakeRings)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8596}\")\n\nYesNoELSE(TakeRings)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8597}\")\n\tSetYesNo(TakeRings)\n\nCommand2(INTL(\"${npc.cpp.intl.554}\"),INTL(\"${npc.cpp.intl.896}\"))\nINTL( 8598, \"If you would assist me, I could use some \\\"Rings\\\" \\\"of\\\" \\\"the\\\" \\\"Lion\\\". King Aedenas Gravesoul, ruler of the \"\n\"Centaurs, should have some, but you might need to give him something in return.\")\n\nCommand(INTL(\"${npc.cpp.intl.8599}\"))\n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8600}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n  \nCommand(INTL(\"${npc.cpp.intl.8601}\"))\n\"\"\nIF(CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8602}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand3(INTL(\"${npc.cpp.intl.738}\"),INTL(\"${npc.cpp.intl.739}\"),INTL(\"${npc.cpp.intl.737}\"))\n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL( 8603, \"The elven Lich's power has grown steadily over the past few thousand years. His strength is so great that it \"\n\t\"rivals that of the gods themselves. Fortunately, Artherk is not the sole god to be affected by the \\\"uprise\\\" of \"\n\t\"Makrsh P'Tangh.\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.8604}\"))\n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL( 8605, \"The uprise of the Dark One has also left the foul \\\"Ogrimar\\\", god of the night, partially drained of his powers \"\n\t\"as well.\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.8606}\"))\n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL( 8607, \"The god of the night, Ogrimar, represents terror and chaos but he is also an unlikely ally in the war \"\n\t\"versus to Makrsh P'Tangh. In fact, some of his \\\"disciples\\\" are gathering followers to launch an assault \"\n\t\"against the lich itself.\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.8608}\")) \n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL( 8609, \"One of his disciples, \\\"Mordenthal\\\", is a dark knight who resides in northern Stoneheim. He is extremely deceitful \"\n\t\"and must not be trusted.\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.8610}\"))\n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL( 8611, \"He is a dark knight and was once foremost amongst the great generals in Ogrimar's army. Even as \"\n\t\"we speak, he is recruiting followers of the dark path to further his master's \\\"cause\\\".\")\t\t\nELSEIF(CheckFlag(__FLAG_FOLLOWER_OF_OGRIMAR) == 1)\n\tConversation\n \tFORMAT(INTL( 8612, \"Hmmmm. I see that you have Mordenthal's leash tied around your neck, %s. There is nothing to say about your \"\n\t\"master except that he'll eventually have to face me and meet his demise at last.\"), USER_NAME) \nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.8613}\")) \n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tFORMAT(INTL( 8614, \"The god Ogrimar seeks the demise of the Dark One. It is also our main \"\n\t\"concern, as followers of Artherk. %s, I'll make this short for both you and I. \"\n\t\"You have been granted the title of Champion of Light back in Raven's Dust. It is \"\n\t\"now time to \\\"fulfill\\\" your destiny and prove that you are indeed worthy of this honor.\"),USER_NAME) \t\nELSE\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t   \n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.8615}\"))\n\"\"\nIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8616}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF \n\nCommand(INTL(\"${npc.cpp.intl.7710}\")) \n\"\"\nIF (CheckFlag(__FLAG_LIGHTBRINGER_OF_ARTHERK) == 1) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8617}\")\nELSEIF (CheckFlag(__QUEST_FIXED_ALIGNMENT) == 1) \n\tConversation\n\tINTL( 8618, \"To become a Lightbringer of Artherk, you need only to pledge to serve Artherk. This is \"\n\t\"an important decision that you are about to choose. Do you feel within your soul that \"\n\t\"you are ready for such commitment?\")\n\tSetYesNo(LIGHTBRINGER) \nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.8586}\")\nENDIF\n\nYES(LIGHTBRINGER)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8619}\")\n\t;YesNo = Pledge;\n\t\nNO(LIGHTBRINGER)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8620}\")\n\nYesNoELSE(LIGHTBRINGER)\n\tConversation\n\tINTL(\"${npc.cpp.intl.8621}\") \t\n\tSetYesNo(LIGHTBRINGER)\n\n;",
        Map.ofEntries(
              Map.entry("OnAttacked", "   \n    switch(rnd(0, 9)){\n    case 0: SHOUT(INTL(\"${npc.cpp.intl.8576}\")); break;\n    case 1: SHOUT(INTL(\"${npc.cpp.intl.8577}\")); break;\n    default: break;\n\t } \nNPCstructure::OnAttacked( UNIT_FUNC_PARAM );\n")
          )));
    out.put("BishopCrowbanner", new NpcScripts.Entry(
        "BishopCrowbanner",
        "NPC RavensDust/BishopCrowbanner.cpp",
        "BishopCrowbannerNPC",
        "InitTalk\n\nBegin\n\"\"\n// If quest has been running for too long.\nIF (CheckGlobalFlag(__GLOBAL_QUEST_CROWBANNER_TIMER) <= CurrentRound)\n    // Invert illness status and reset timer.\n\tGiveGlobalFlag(__QUEST_BISHOP_ILLNESS, abs(CheckGlobalFlag(__QUEST_BISHOP_ILLNESS)-1))\n\tGiveGlobalFlag(__GLOBAL_QUEST_CROWBANNER_TIMER, rnd.roll(dice(1,6))*4 HOURS TDELAY)\nENDIF\nIF (CheckGlobalFlag(__QUEST_BISHOP_ILLNESS) == 1)\n\tConversation\n\tINTL(\"${npc.cpp.intl.6171}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.6172}\")\n\tBREAK\nENDIF\n\nCommand2(INTL(\"${npc.cpp.intl.2034}\"),INTL(\"${npc.cpp.intl.2035}\"))\nINTL(\"${npc.cpp.intl.3777}\")\nBREAK\n\nCmdAND(INTL(\"${npc.cpp.intl.6126}\"),INTL(\"${npc.cpp.intl.4275}\"))\nINTL( 7133, \"I'm afraid I have no time for this. If you're interested in riddles, why don't you ask \"\n\"Menark? He's quite fond of riddles. I think he knows the answer to six thousand riddles, \"\n\"so he's got to have the answer to the one that bothers you.\")\n\nCommand(INTL(\"${npc.cpp.intl.4545}\"))\nINTL(\"${npc.cpp.intl.6173}\")\n\nCommand(INTL(\"${npc.cpp.intl.4547}\"))\nINTL( 6174, \"I am the Bishop Crowbanner! If you truly have to say something to me, \"\n\"do it properly by using my holy title.\")\n\nCmdAND(INTL(\"${npc.cpp.intl.1999}\"),INTL(\"${npc.cpp.intl.4648}\"))\n\"\"\nIF (CheckItem(__OBJ_POISON_APPLE) >= 1) // Got a poison apple?\n\tConversation\n\tINTL(\"${npc.cpp.intl.6175}\")\n\tGiveGlobalFlag(__QUEST_BISHOP_ILLNESS,0)\n\tGiveGlobalFlag(__GLOBAL_QUEST_CROWBANNER_TIMER, rnd.roll(dice(1,6))*4 HOURS TDELAY)\n\tIF (CheckFlag(__QUEST_SEEK_SHADEEN) <= 1) // If PC never gave poison to bishop before:\n\t\tGiveFlag(__QUEST_SEEK_SHADEEN, 2)\n\t\tIF (USER_KARMA > (-100*(CheckFlag(__QUEST_ISLAND_ACCESS)+1)))\n\t\t\tGiveKarma(-25 * ( 500 + USER_KARMA ) / 500)\n\t\tENDIF\n\tENDIF\n\tTakeItem(__OBJ_POISON_APPLE)\nELSE // Don't got no poison apple to give...\n\tIF (CheckItem(__OBJ_APPLE) >= 1) //...but got a real one:\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.6176}\")\n\t\tTakeItem(__OBJ_APPLE)\n\tELSE //...and don't got no apple to give either:\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.6177}\")\n\tENDIF\nENDIF\n\nCommand4(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.543}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.1001}\"))\n\"\"\nIF (CheckFlag(__BALORK_BRAND) == 0)\n\tConversation\n\tINTL(\"${npc.cpp.intl.6178}\")\nELSE\n\tConversation\n\tINTL( 6179, \"I see that you too bear the brand of Balork. Perhaps my pupil, Princess Delilah, \"\n\t\"could be of some assistance. Perhaps you should ask her about \\\"Balork\\\".\")\nENDIF\n\nCommand2(INTL(\"${npc.cpp.intl.3694}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.6180}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.3696}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL(\"${npc.cpp.intl.6181}\")\n\nCommand3(INTL(\"${npc.cpp.intl.700}\"),INTL(\"${npc.cpp.intl.495}\"),INTL(\"${npc.cpp.intl.496}\"))\nINTL(\"${npc.cpp.intl.7547}\")\nCreateSkillList\n\t//AddTeachSkill (__SPELL_SANCTUARY, 33, 99632) // steph dsactivation\n\tAddTeachSkill (__SPELL_HEALING, 35, 110825)\nSendTeachSkillList\n\nCommand2(INTL(\"${npc.cpp.intl.4541}\"),INTL(\"${npc.cpp.intl.1005}\"))\nINTL(\"${npc.cpp.intl.6183}\") \n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\"))\nINTL(\"${npc.cpp.intl.6184}\")\nBREAK\n\nCommand5(INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.520}\"))\nINTL(\"${npc.cpp.intl.6185}\")\nBREAK\n\nDefault\nINTL(\"${npc.cpp.intl.2492}\")\n\nEndTalk",
        Map.of()));
