    out.put("DerranIronstrife", new NpcScripts.Entry(
        "DerranIronstrife",
        "NPC RavensDust/DerranIronstrife.cpp",
        "DerranIronstrifeNPC",
        "InitTalk\n\nBegin\n\"\"\nIF (CheckNPCFlag (__FLAG_DELAY_DERRAN) > CurrentRound) // This means the delay is not over yet\nELSEIF (CheckGlobalFlag(__GLOBAL_FLAG_ORC_QUEST) == 1) // This means the Quest is running\n// Do nothing since the Quest is already running. \nELSE   \n\tIF (rnd.roll(dice(1, 25) ) == 1)\n\t\tSUMMON( \"ORCARCHMAGE\", 1395, 1830) // Summons the orcish great mage in Raven's Dust orc camp\n\t\tGiveGlobalFlag(__GLOBAL_FLAG_ORC_QUEST, 1) // Orc great mage is now running\n\tELSE\n\t\tGiveNPCFlag (__FLAG_DELAY_DERRAN, rnd.roll(dice(3, 4 ) ) MINUTES TDELAY)\n\tENDIF\nENDIF\t\nIF (CheckFlag(__DERRAN_KNOWS_YOU) >= 1)\n\tConversation\n   FORMAT(INTL(\"${npc.cpp.intl.4655}\"), USER_NAME)\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.4656}\")\n\tSetYesNo( KNOWLEDGE )\nENDIF\n\nYES ( KNOWLEDGE )\n\tConversation\n   FORMAT(INTL(\"${npc.cpp.intl.4657}\"), USER_NAME)\n   GiveFlag( __DERRAN_KNOWS_YOU, 1 )\n\nNO ( KNOWLEDGE )\n\tConversation\n\tINTL(\"${npc.cpp.intl.4658}\") \n\nYesNoELSE ( KNOWLEDGE )\n\tConversation\n\tINTL(\"${npc.cpp.intl.4659}\")\n\tSetYesNo( KNOWLEDGE ) \n\t\nCommand2(INTL(\"${npc.cpp.intl.485}\"),INTL(\"${npc.cpp.intl.3694}\"))\nINTL(\"${npc.cpp.intl.4660}\")\n\nCommand2(INTL(\"${npc.cpp.intl.4661}\"),INTL(\"${npc.cpp.intl.4662}\"))\nINTL( 4663, \"Yes, I am Derran Ironstrife. I already told you that didn't I? You could have asked me simply \"\n\"by asking me my \\\"name\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.1460}\"))\nINTL(\"${npc.cpp.intl.4664}\")\n\nCommand3(INTL(\"${npc.cpp.intl.3990}\"),INTL(\"${npc.cpp.intl.1072}\"),INTL(\"${npc.cpp.intl.754}\"))\nINTL(\"${npc.cpp.intl.4665}\")\n\nCommand3(INTL(\"${npc.cpp.intl.3696}\"),INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 4666, \"I am a warrior fighting for the good cause of our King. I also help \\\"train\\\" \"\n\"those who are willing to fight the orc menace. Sometimes, we attack the orcs to prevent \"\n\"their siege weapons from approaching within range of the castle's walls. Sadly, we aren't \"\n\"able to eradicate them once and for all. I heard they often hide in the surrounding \\\"caverns\\\".\")\n\nCommand(INTL(\"${npc.cpp.intl.502}\"))\nINTL(\"${npc.cpp.intl.2392}\")\nCreateSkillList\n\tAddTrainSkill( __SKILL_ATTACK, 5000, 10 )\n\tAddTrainSkill( __SKILL_STUN_BLOW, 100, 20 )\n\tAddTrainSkill( __SKILL_POWERFULL_BLOW, 100, 50 )\nSendTrainSkillList\n\nCommand(INTL(\"${npc.cpp.intl.744}\"))\nINTL( 4667, \"I hate those orcs. Their leader, Ghundarg, almost killed me the other day. He cowardly attacked me \"\n\"from behind. Someday, I'll get my revenge...\")\n\nCommand(INTL(\"${npc.cpp.intl.881}\"))\nINTL( 4668, \"There are many caverns on the island of Raven's Dust. You should always bring a few torches if you wish \"\n\"to explore them. Oh, and bring a sword, that will prove useful too. Trust me.\") \n\nCommand2(INTL(\"${npc.cpp.intl.1492}\"),INTL(\"${npc.cpp.intl.3865}\"))\nINTL(\"${npc.cpp.intl.4669}\")\n\nCommand(INTL(\"${npc.cpp.intl.3854}\"))\nINTL(\"${npc.cpp.intl.4670}\")\n\nCommand(INTL(\"${npc.cpp.intl.793}\"))\nINTL(\"${npc.cpp.intl.4671}\")\n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.698}\"),INTL(\"${npc.cpp.intl.697}\"))\nINTL(\"${npc.cpp.intl.4672}\")\nBREAK\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.520}\"))\n\"\"\nIF (CheckFlag(__DERRAN_KNOWS_YOU) >= 1) \n\tConversation\n\tINTL(\"${npc.cpp.intl.4673}\")\n\tBREAK\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.4674}\")\n\tBREAK\nENDIF\n\t\nDefault \nINTL(\"${npc.cpp.intl.4675}\")\n\nEndTalk",
        Map.of()));
